-- =====================================================================
-- Golden Mart Myanmar - DEMO / TEST DATA for Shagan POS  (generated file)
--
-- One fully populated organization: 3 branches, 6 registers, 12 staff,
-- 42 products, 3 combos, 5 suppliers, 30 customers and 21 days of trading
-- (sales, payments, voids, returns, exchanges, shifts, cash reconciliation,
-- expenses, purchase orders, goods receipts, stock transfers/adjustments,
-- inventory ledger, audit log, held sales, sync conflicts, receipt settings).
--
-- PREREQUISITE: the tables must exist - run the API once (`go run ./cmd`) so
-- it migrates. Roles/permissions are created here if missing, so
-- `go run ./cmd/seed` is not required first.
--
-- SAFE TO RUN ON A NON-EMPTY DATABASE: ids are allocated after the current
-- maximum, sequences are advanced afterwards, and the whole file is one
-- atomic statement (all or nothing). It refuses to run twice.
-- All dates are relative to the moment you run it ("today" = Asia/Yangon).
--
-- LOGINS (all passwords: Demo@1234)
--   owner            owner@goldenmart.test
--   service_center   servicecenter@goldenmart.test
--   POS terminals    pos.ygn1@goldenmart.test  pos.ygn2@...  pos.mdy1@...  pos.mdy2@...
--                    pos.npt1@...  pos.npt2@...      (Register 1 / 2 of each branch)
-- STAFF PINs (6 digits, sign in at a POS terminal)
--   manager 111111 | super staff 222222 | cashiers 333333
--   per branch: manager, super staff, cashier A, cashier B (see staffs table)
--   Register 1 of every branch has an OPEN shift today; Register 2 is free.
-- =====================================================================
\set ON_ERROR_STOP on

DO $seed$
DECLARE
  base timestamptz := date_trunc('day', now() AT TIME ZONE 'Asia/Yangon') AT TIME ZONE 'Asia/Yangon';
  d0 date := (now() AT TIME ZONE 'Asia/Yangon')::date;
  r_staff bigint; r_super bigint; r_manager bigint;

  o_branches bigint;
  o_devices bigint;
  o_users bigint;
  o_staffs bigint;
  o_customers bigint;
  o_customer_consents bigint;
  o_categories bigint;
  o_products bigint;
  o_combos bigint;
  o_combo_items bigint;
  o_suppliers bigint;
  o_purchase_orders bigint;
  o_purchase_order_items bigint;
  o_goods_receipts bigint;
  o_goods_receipts_items bigint;
  o_stock_levels bigint;
  o_stock_adjustments bigint;
  o_stock_transfers bigint;
  o_stock_transfers_items bigint;
  o_inventory_ledger bigint;
  o_shifts bigint;
  o_shifts_reconciliations bigint;
  o_drawer_events bigint;
  o_expenses bigint;
  o_sale_items bigint;
  o_payments bigint;
  o_held_sales bigint;
  o_voids bigint;
  o_returns bigint;
  o_return_items bigint;
  o_exchanges bigint;
  o_exchange_items bigint;
  o_audit_log bigint;
  o_sync_conflicts bigint;
  o_receipt_settings bigint;
  o_payment_qr_codes bigint;
  o_organizations bigint;
BEGIN
  IF EXISTS (SELECT 1 FROM organizations WHERE name = 'Golden Mart Myanmar') THEN
    RAISE EXCEPTION 'Demo organization % already exists - nothing was changed.', 'Golden Mart Myanmar';
  END IF;

  -- baseline reference data (same content as `go run ./cmd/seed`; idempotent)
    WHERE NOT EXISTS (SELECT 1 FROM roles r WHERE r.code = v.c);
    WHERE NOT EXISTS (SELECT 1 FROM permissions p WHERE p.code = v.c);
    SELECT r.id, p.id FROM (VALUES
      ('staff','access_pos_portal'),
      ('super_staff','access_pos_portal'),('super_staff','open_drawer_no_sale'),('super_staff','apply_manual_discount'),
      ('manager','access_pos_portal'),('manager','access_backoffice'),('manager','apply_manual_discount'),
      ('manager','approve_void'),('manager','approve_return'),('manager','approve_exchange')) g(rc,pc)
    JOIN roles r ON r.code = g.rc JOIN permissions p ON p.code = g.pc
    WHERE NOT EXISTS (SELECT 1 FROM role_permission x WHERE x.role_id = r.id AND x.permission_id = p.id);
  SELECT id INTO r_staff FROM roles WHERE code = 'staff';
  SELECT id INTO r_super FROM roles WHERE code = 'super_staff';
  SELECT id INTO r_manager FROM roles WHERE code = 'manager';

  SELECT COALESCE(MAX(id), 0) INTO o_branches FROM branches;
  SELECT COALESCE(MAX(id), 0) INTO o_devices FROM devices;
  SELECT COALESCE(MAX(id), 0) INTO o_users FROM users;
  SELECT COALESCE(MAX(id), 0) INTO o_staffs FROM staffs;
  SELECT COALESCE(MAX(id), 0) INTO o_customers FROM customers;
  SELECT COALESCE(MAX(id), 0) INTO o_customer_consents FROM customer_consents;
  SELECT COALESCE(MAX(id), 0) INTO o_categories FROM categories;
  SELECT COALESCE(MAX(id), 0) INTO o_products FROM products;
  SELECT COALESCE(MAX(id), 0) INTO o_combos FROM combos;
  SELECT COALESCE(MAX(id), 0) INTO o_combo_items FROM combo_items;
  SELECT COALESCE(MAX(id), 0) INTO o_suppliers FROM suppliers;
  SELECT COALESCE(MAX(id), 0) INTO o_purchase_orders FROM purchase_orders;
  SELECT COALESCE(MAX(id), 0) INTO o_purchase_order_items FROM purchase_order_items;
  SELECT COALESCE(MAX(id), 0) INTO o_goods_receipts FROM goods_receipts;
  SELECT COALESCE(MAX(id), 0) INTO o_goods_receipts_items FROM goods_receipts_items;
  SELECT COALESCE(MAX(id), 0) INTO o_stock_levels FROM stock_levels;
  SELECT COALESCE(MAX(id), 0) INTO o_stock_adjustments FROM stock_adjustments;
  SELECT COALESCE(MAX(id), 0) INTO o_stock_transfers FROM stock_transfers;
  SELECT COALESCE(MAX(id), 0) INTO o_stock_transfers_items FROM stock_transfers_items;
  SELECT COALESCE(MAX(id), 0) INTO o_inventory_ledger FROM inventory_ledger;
  SELECT COALESCE(MAX(id), 0) INTO o_shifts FROM shifts;
  SELECT COALESCE(MAX(id), 0) INTO o_shifts_reconciliations FROM shifts_reconciliations;
  SELECT COALESCE(MAX(id), 0) INTO o_drawer_events FROM drawer_events;
  SELECT COALESCE(MAX(id), 0) INTO o_expenses FROM expenses;
  SELECT COALESCE(MAX(id), 0) INTO o_sale_items FROM sale_items;
  SELECT COALESCE(MAX(id), 0) INTO o_payments FROM payments;
  SELECT COALESCE(MAX(id), 0) INTO o_held_sales FROM held_sales;
  SELECT COALESCE(MAX(id), 0) INTO o_voids FROM voids;
  SELECT COALESCE(MAX(id), 0) INTO o_returns FROM returns;
  SELECT COALESCE(MAX(id), 0) INTO o_return_items FROM return_items;
  SELECT COALESCE(MAX(id), 0) INTO o_exchanges FROM exchanges;
  SELECT COALESCE(MAX(id), 0) INTO o_exchange_items FROM exchange_items;
  SELECT COALESCE(MAX(id), 0) INTO o_audit_log FROM audit_log;
  SELECT COALESCE(MAX(id), 0) INTO o_sync_conflicts FROM sync_conflicts;
  SELECT COALESCE(MAX(id), 0) INTO o_receipt_settings FROM receipt_settings;
  SELECT COALESCE(MAX(id), 0) INTO o_payment_qr_codes FROM payment_qr_codes;
  SELECT COALESCE(MAX(id), 0) INTO o_organizations FROM organizations;


  -- advance every id sequence past the rows just inserted
  PERFORM setval(pg_get_serial_sequence('branches', 'id'), (SELECT MAX(id) FROM branches));
  PERFORM setval(pg_get_serial_sequence('devices', 'id'), (SELECT MAX(id) FROM devices));
  PERFORM setval(pg_get_serial_sequence('users', 'id'), (SELECT MAX(id) FROM users));
  PERFORM setval(pg_get_serial_sequence('staffs', 'id'), (SELECT MAX(id) FROM staffs));
  PERFORM setval(pg_get_serial_sequence('customers', 'id'), (SELECT MAX(id) FROM customers));
  PERFORM setval(pg_get_serial_sequence('customer_consents', 'id'), (SELECT MAX(id) FROM customer_consents));
  PERFORM setval(pg_get_serial_sequence('categories', 'id'), (SELECT MAX(id) FROM categories));
  PERFORM setval(pg_get_serial_sequence('products', 'id'), (SELECT MAX(id) FROM products));
  PERFORM setval(pg_get_serial_sequence('combos', 'id'), (SELECT MAX(id) FROM combos));
  PERFORM setval(pg_get_serial_sequence('combo_items', 'id'), (SELECT MAX(id) FROM combo_items));
  PERFORM setval(pg_get_serial_sequence('suppliers', 'id'), (SELECT MAX(id) FROM suppliers));
  PERFORM setval(pg_get_serial_sequence('purchase_orders', 'id'), (SELECT MAX(id) FROM purchase_orders));
  PERFORM setval(pg_get_serial_sequence('purchase_order_items', 'id'), (SELECT MAX(id) FROM purchase_order_items));
  PERFORM setval(pg_get_serial_sequence('goods_receipts', 'id'), (SELECT MAX(id) FROM goods_receipts));
  PERFORM setval(pg_get_serial_sequence('goods_receipts_items', 'id'), (SELECT MAX(id) FROM goods_receipts_items));
  PERFORM setval(pg_get_serial_sequence('stock_levels', 'id'), (SELECT MAX(id) FROM stock_levels));
  PERFORM setval(pg_get_serial_sequence('stock_adjustments', 'id'), (SELECT MAX(id) FROM stock_adjustments));
  PERFORM setval(pg_get_serial_sequence('stock_transfers', 'id'), (SELECT MAX(id) FROM stock_transfers));
  PERFORM setval(pg_get_serial_sequence('stock_transfers_items', 'id'), (SELECT MAX(id) FROM stock_transfers_items));
  PERFORM setval(pg_get_serial_sequence('inventory_ledger', 'id'), (SELECT MAX(id) FROM inventory_ledger));
  PERFORM setval(pg_get_serial_sequence('shifts', 'id'), (SELECT MAX(id) FROM shifts));
  PERFORM setval(pg_get_serial_sequence('shifts_reconciliations', 'id'), (SELECT MAX(id) FROM shifts_reconciliations));
  PERFORM setval(pg_get_serial_sequence('drawer_events', 'id'), (SELECT MAX(id) FROM drawer_events));
  PERFORM setval(pg_get_serial_sequence('expenses', 'id'), (SELECT MAX(id) FROM expenses));
  PERFORM setval(pg_get_serial_sequence('sale_items', 'id'), (SELECT MAX(id) FROM sale_items));
  PERFORM setval(pg_get_serial_sequence('payments', 'id'), (SELECT MAX(id) FROM payments));
  PERFORM setval(pg_get_serial_sequence('held_sales', 'id'), (SELECT MAX(id) FROM held_sales));
  PERFORM setval(pg_get_serial_sequence('voids', 'id'), (SELECT MAX(id) FROM voids));
  PERFORM setval(pg_get_serial_sequence('returns', 'id'), (SELECT MAX(id) FROM returns));
  PERFORM setval(pg_get_serial_sequence('return_items', 'id'), (SELECT MAX(id) FROM return_items));
  PERFORM setval(pg_get_serial_sequence('exchanges', 'id'), (SELECT MAX(id) FROM exchanges));
  PERFORM setval(pg_get_serial_sequence('exchange_items', 'id'), (SELECT MAX(id) FROM exchange_items));
  PERFORM setval(pg_get_serial_sequence('audit_log', 'id'), (SELECT MAX(id) FROM audit_log));
  PERFORM setval(pg_get_serial_sequence('sync_conflicts', 'id'), (SELECT MAX(id) FROM sync_conflicts));
  PERFORM setval(pg_get_serial_sequence('receipt_settings', 'id'), (SELECT MAX(id) FROM receipt_settings));
  PERFORM setval(pg_get_serial_sequence('payment_qr_codes', 'id'), (SELECT MAX(id) FROM payment_qr_codes));
  PERFORM setval(pg_get_serial_sequence('organizations', 'id'), (SELECT MAX(id) FROM organizations));

  RAISE NOTICE 'Golden Mart Myanmar demo data loaded (org id %).', o_organizations + 1;
END
$seed$;
